#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the software factory setup (#189).
#
#   scripts/factory/setup-wizard.sh                    all stages; done ones are skipped
#   scripts/factory/setup-wizard.sh check              read-only summary
#   scripts/factory/setup-wizard.sh rotate TOKEN       gate, publish, subscription, or agent
#   scripts/factory/setup-wizard.sh revoke TOKEN       also when a token may have leaked
#   scripts/factory/setup-wizard.sh cleanup            remove negative-test leftovers
#
# Run it from a clean checkout of main, up to date; it checks. It never sets
# FACTORY_ENABLED and changes nothing unless that is unset or exactly false, except
# to revoke a token or clean up. Tokens go only through the hidden prompt in
# setup_steps.py. Nothing is saved locally; progress is read from GitHub.
# No confirmation has a default: declining stops the wizard, so run it again later.
# ──────────────────────────────────────────────────────────────────────────

set +x +a
# The library's own writers are not used: secrets here never reach a shell.
ENV_FILE=/dev/null
write_env()  { exit 70; }
set_secret() { exit 70; }
set_var()    { exit 70; }
ask_secret() { exit 70; }

# The library's prompts show what is typed, so they say so.
confirm() {
  local reply=""
  printf '  %s? %s [y/N, visible; never paste a token here]%s ' "$YELLOW" "$1" "$RESET"
  read -r reply || true
  shown "$reply"
  [[ "$reply" =~ ^[Yy] ]]
}
pause() {
  local reply=""
  printf '  %s%s (visible; never paste a token here)%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r reply || true
  shown "$reply"
}
shown() {
  if (( ${#1} > 30 )); then
    warn "If that was a token, the terminal has shown it: revoke it now."
    exit 1
  fi
}

HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
GITHUB=https://github.com/sspeaks/redis-client
PAT=https://github.com/settings/personal-access-tokens

steps() { python3 -I "$HERE/setup_steps.py" "$@"; }

stop() {
  warn "Stopped here. Run the wizard again to go on; finished stages are skipped."
  exit 1
}

# until_done STEP...: run it until it succeeds or the maintainer stops.
until_done() {
  until steps "$@"; do
    confirm "Not done yet. Try again?" || stop
  done
}

# already STEP...: quietly succeed when the stage is done.
already() { steps "$@" 2>/dev/null; }

# try_done STEP...: as until_done, but giving up only fails.
try_done() {
  until steps "$@"; do
    confirm "Not done yet. Try again?" || return 1
  done
}

environment_stage() { # NAME, then one instruction per argument
  local name="$1"; shift
  stage "Environment $name"
  already check environment "$name" && return
  open_url "$GITHUB/settings/environments"
  step "Open $name, or choose New environment and name it exactly: $name"
  local line; for line in "$@"; do step "$line"; done
  step "Turn OFF \"Allow administrators to bypass configured protection rules\"."
  step "Save the protection rules."
  until_done check environment "$name"
}

REVIEWER="Required reviewers: on, only sspeaks. Leave \"Prevent self-review\" off."
MAIN_ONLY="Deployment branches and tags: Selected branches and tags; one BRANCH rule named main, no tag rule."

token_notes() { # gate | publish | subscription
  case "$1" in
    gate)
      open_url "$PAT/new"
      step "Fine-grained token named factory-gate, owner sspeaks, expiry one year or less."
      step "Only select repositories: redis-client."
      step "Repository permissions, all READ-ONLY: Actions, Contents, Issues, Variables. Nothing else."
      ;;
    publish)
      open_url "$PAT/new"
      step "Fine-grained token named factory-publish, owner sspeaks, expiry one year or less."
      step "Only select repositories: redis-client."
      step "Repository permissions, all READ AND WRITE: Contents, Issues, Pull requests. Nothing else."
      say  "It is tested first and stored only if every forbidden action is refused."
      ;;
    subscription | agent)
      open_url "https://claude.ai/settings/usage"
      step "Turn usage credits OFF."
      step "Find where a setup-token is revoked in your Claude account. The docs checked do not say;"
      step "if you cannot find it, stop here."
      step "Make a NEW token for this environment; never reuse the other environment's."
      step "In ANOTHER terminal run: claude setup-token"
      step "Copy the token. Do not save it. Close that terminal and clear its scrollback afterwards."
      ;;
  esac
  step "Generate, copy, and paste it only at the hidden prompt."
}

token_stage() { # KIND TITLE
  stage "$2"
  if confirm "Is this token already stored, and tested by this wizard?"; then
    until_done stored "$1"
  else
    token_notes "$1"
    until_done token "$1"
  fi
}

final_checks() {
  local bad=0 name
  steps check preflight || bad=1
  steps check checkout || bad=1
  steps check leftovers || bad=1
  steps check workflows || bad=1
  steps check switch || bad=1
  for name in release factory-model factory-publish factory-resume factory-agent; do
    steps check environment "$name" || bad=1
  done
  steps check labels || bad=1
  steps check forks || bad=1
  steps check tags || bad=1
  steps check main || bad=1
  steps check mergeable || bad=1
  steps check copies || bad=1
  steps check credits || bad=1
  for name in gate publish subscription agent; do
    steps check missing "$name" || bad=1
  done
  steps check resumed || bad=1
  return "$bad"
}

token_name() {
  case "${1:-}" in
    gate | publish | subscription | agent) ;;
    *) warn "Name a token: gate, publish, subscription, or agent."; exit 2 ;;
  esac
}

# Nothing here needs the old token, and no answer stops the later steps.
revoke_old() { # KIND
  if [[ "$1" == subscription || "$1" == agent ]]; then
    step "Revoke the old setup-token in your Claude account, where you found the control."
  else
    open_url "$PAT"
    step "Delete the old token. Check its last-used date and compare it with the factory's runs."
  fi
  try_done revoked "$1"
}

rotate() { # KIND
  local failed=0
  token_name "$1"
  if [[ "$1" == publish ]]; then TOTAL_STAGES=4; else TOTAL_STAGES=2; fi
  banner "Rotate the $1 token"
  until_done cleanup
  say "First set FACTORY_ENABLED to false yourself, and let running factory jobs finish."
  until_done check switch
  if [[ "$1" == publish ]]; then
    stage "Factory resume run for the negative test"
    try_done dispatch-resume || failed=1
  fi
  stage "Replace the token"
  token_notes "$1"
  try_done token "$1" || failed=1
  if [[ "$1" == publish ]]; then
    stage "Reject the resume run"
    open_url "$GITHUB/actions/workflows/factory-resume.yml"
    step "REJECT the waiting run, unless you want to clear every pause before it."
    pause "Press Enter when done"
  fi
  stage "Revoke the old token"
  revoke_old "$1" || failed=1
  if (( failed )); then
    say "Not everything is done. The stored copies may still hold the old token."
    try_done unset "$1" || true
    warn "Keep FACTORY_ENABLED off and run: rotate $1"
    exit 1
  fi
  say "The new token is in place. Turn FACTORY_ENABLED on again yourself when you want it."
}

revoke() { # KIND
  local failed=0
  token_name "$1"
  TOTAL_STAGES=2
  banner "Revoke the $1 token"
  say "Set FACTORY_ENABLED to false yourself and cancel running factory jobs, now."
  stage "Revoke it where it was made"
  revoke_old "$1" || failed=1
  stage "Delete the stored copies"
  try_done unset "$1" || failed=1
  step "If it may have leaked: delete logs or artifacts that hold it, and check the repository's"
  step "recent commits, issues and pull requests for work you do not recognize."
  step "Do not start factory jobs again until the cause is known. Then use: rotate $1"
  if (( failed )); then
    warn "NOT finished: the token may still work, or copies may remain. Run: revoke $1"
    exit 1
  fi
}

run_wizard() {

TOTAL_STAGES=19

banner "Software factory setup"

stage "Before anything changes"
say "This reads GitHub as sspeaks and checks that the factory is off."
until_done check preflight
until_done cleanup
until_done check checkout
until_done check switch
until_done check copies

environment_stage release "$REVIEWER"
stage "Environment factory-model (set up for the live proof)"
until_done check environment factory-model
environment_stage factory-publish "No required reviewers and no wait timer." "$MAIN_ONLY"
environment_stage factory-resume "$REVIEWER" "$MAIN_ONLY"
environment_stage factory-agent "No required reviewers and no wait timer: unattended agent jobs use it." \
  "$MAIN_ONLY"

stage "Labels"
until_done labels
say "Never rename or delete factory-paused, and never put these in an issue template."

stage "Tag ruleset"
say "It must block creating, updating and deleting every tag, with no bypass."
already check tags || {
  open_url "$GITHUB/settings/rules"
  step "Tag ruleset, active, all tags, empty bypass list: restrict creations, updates, deletions."
  until_done check tags
}

stage "Fork pull request workflows"
already check forks || {
  open_url "$GITHUB/settings/actions"
  step "Approval for running fork pull request workflows: require approval for ALL external contributors."
  step "Save."
  until_done check forks
}

stage "How GitHub records pauses"
say "A test run shows the gate stops after a failed pause and ignores a skipped one."
until_done check workflows
until_done setup-test

token_stage gate "Gate token (read-only)"

stage "A Factory resume run that waits"
say "The negative test needs a run that waits for approval. You approve it in a later stage."
if already check resumed; then
  say "A resume was approved before."
  if confirm "Will you replace the publish token now?"; then until_done dispatch-resume; fi
else
  until_done dispatch-resume
fi

token_stage publish "Publish token and negative test"

stage "Subscription token of the live proof"
say "It stays in factory-model, which waits for your approval."
until_done stored subscription

stage "Usage credits, for unattended runs"
already check credits || {
  open_url "https://claude.ai/settings/usage"
  step "Check that usage credits are OFF."
  until_done usage-credits
}

token_stage agent "Subscription token for unattended agent jobs"

stage "Remove the administrator bypass on main (last setting to change)"
say "After this you also need a pull request and a green build for every change to main."
already check main || {
  say "First: can you still merge alone afterwards?"
  until_done check mergeable
  say "If you are locked out later: as an administrator you can always edit rulesets. Open"
  say "$GITHUB/settings/rules, ruleset main, and add \"Repository admin\" to the bypass"
  say "list again, or fix the rule that blocks you. Then run this wizard's check again."
  open_url "$GITHUB/settings/rules"
  step "Open ruleset main. Remove every entry from its bypass list. Save."
  until_done check main
}

stage "Approve one resume"
if already check resumed; then
  say "If a resume run still waits, reject it in the browser."
else
  say "This clears the setup test's refusal and proves the approval works."
  open_url "$GITHUB/actions/workflows/factory-resume.yml"
  step "Open the waiting run, choose Review deployments, approve factory-resume, wait until it is green."
  until_done resume
fi

stage "Final checks"
final_checks || stop
until_done attest usage-credits
say "Setup is verified. FACTORY_ENABLED is still off; turning it on is your decision, not this wizard's."
say "Still to do outside this wizard before launch:"
step "Run Factory sandbox proof, then the remaining launch checks in docs/factory.md."
step "Retire the squad labels, calibrate the performance gate, and do the live checks of #183 to #192."
say "Later: rotate GitHub tokens before they expire, and the subscription token within one year."

}

main() {
  case "${1:-}" in
    "") run_wizard ;;
    check) final_checks ;;
    rotate) rotate "${2:-}" ;;
    revoke) revoke "${2:-}" ;;
    cleanup) steps cleanup ;;
    *) warn "Unknown command: $1"; exit 2 ;;
  esac
}

main "$@"; exit
